/**
 * EPUB 3 Media Overlays (SMIL 3.0) Parser
 *
 * Implements W3C EPUB 3 Media Overlays specification for synchronized narration
 * and forced-alignment ebooks (as generated by the Storyteller platform and EPUB 3 publishers).
 */

export interface SmilPar {
  id: string;
  chapterHref: string; // Base filename of the XHTML chapter (e.g. "chapter1.xhtml")
  elementId?: string;  // HTML ID of the target element/sentence (e.g. "sentence-1")
  audioSrc: string;    // Relative path of audio asset (e.g. "audio/part1.mp3")
  clipBegin: number;   // Timestamp in seconds
  clipEnd: number;     // Timestamp in seconds
}

export interface SmilOverlayCollection {
  // Map of chapter base filename (e.g. "chapter1.xhtml") to list of SMIL pars
  chapterMap: Map<string, SmilPar[]>;
  totalPars: number;
}

/**
 * Parses SMIL clock value string into seconds.
 * Supports:
 * - Full clock: "01:23:45.678" -> 5025.678
 * - Partial clock: "05:23.450" -> 323.45
 * - Timecount seconds: "123.45s" -> 123.45
 * - Timecount milliseconds: "12345ms" -> 12.345
 * - Plain number: "123.45" -> 123.45
 */
export function parseSmilClock(val: string | null | undefined): number {
  if (!val) return 0;
  const str = val.trim();
  if (str.endsWith("ms")) {
    const num = parseFloat(str.slice(0, -2));
    return isNaN(num) ? 0 : num / 1000;
  }
  if (str.endsWith("s")) {
    const num = parseFloat(str.slice(0, -1));
    return isNaN(num) ? 0 : num;
  }
  if (str.includes(":")) {
    const parts = str.split(":").map((p) => parseFloat(p));
    if (parts.some((p) => isNaN(p))) return 0;
    if (parts.length === 3) {
      return parts[0] * 3600 + parts[1] * 60 + parts[2];
    }
    if (parts.length === 2) {
      return parts[0] * 60 + parts[1];
    }
  }
  const direct = parseFloat(str);
  return isNaN(direct) ? 0 : direct;
}

/**
 * Parses an individual SMIL XML document and returns extracted <par> items.
 */
export function parseSmilDocument(smilXml: string, smilPath: string): SmilPar[] {
  const pars: SmilPar[] = [];
  try {
    const parser = new DOMParser();
    const doc = parser.parseFromString(smilXml, "application/xml");

    const parElements = doc.getElementsByTagName("par");
    for (let i = 0; i < parElements.length; i++) {
      const par = parElements[i];
      const textNode = par.getElementsByTagName("text")[0];
      const audioNode = par.getElementsByTagName("audio")[0];

      if (!textNode || !audioNode) continue;

      const textSrc = textNode.getAttribute("src") || "";
      const audioSrc = audioNode.getAttribute("src") || "";
      const clipBeginStr = audioNode.getAttribute("clipBegin");
      const clipEndStr = audioNode.getAttribute("clipEnd");

      if (!textSrc) continue;

      const [textHref, elemId] = textSrc.split("#");
      const baseChapterHref = textHref.split("/").pop() || textHref;

      const clipBegin = parseSmilClock(clipBeginStr);
      const clipEnd = parseSmilClock(clipEndStr);

      pars.push({
        id: par.getAttribute("id") || `smil-par-${i}`,
        chapterHref: baseChapterHref,
        elementId: elemId || undefined,
        audioSrc,
        clipBegin,
        clipEnd: clipEnd > clipBegin ? clipEnd : clipBegin + 3,
      });
    }
  } catch (err) {
    console.warn(`Failed to parse SMIL file (${smilPath}):`, err);
  }
  return pars;
}

/**
 * Discovers and parses all EPUB 3 Media Overlay SMIL files inside an epubjs Book.
 */
export async function parseBookMediaOverlays(book: any): Promise<SmilOverlayCollection> {
  const chapterMap = new Map<string, SmilPar[]>();
  let totalPars = 0;

  if (!book?.archive?.zip?.files) {
    return { chapterMap, totalPars: 0 };
  }

  try {
    const files = book.archive.zip.files;
    const smilPaths: string[] = Object.keys(files).filter((path) =>
      path.toLowerCase().endsWith(".smil")
    );

    if (smilPaths.length === 0) {
      return { chapterMap, totalPars: 0 };
    }

    for (const smilPath of smilPaths) {
      try {
        const smilXml = await book.archive.getText(smilPath);
        if (!smilXml) continue;
        const parsed = parseSmilDocument(smilXml, smilPath);
        for (const p of parsed) {
          const list = chapterMap.get(p.chapterHref) || [];
          list.push(p);
          chapterMap.set(p.chapterHref, list);
          totalPars++;
        }
      } catch (smilErr) {
        console.warn(`Error reading SMIL resource ${smilPath}:`, smilErr);
      }
    }

    // Sort pars chronologically by clipBegin for each chapter
    for (const [ch, list] of chapterMap.entries()) {
      list.sort((a, b) => a.clipBegin - b.clipBegin);
    }
  } catch (err) {
    console.warn("Failed inspecting book for EPUB 3 Media Overlays:", err);
  }

  return { chapterMap, totalPars };
}
